-- Catalog guided create: schema, product CRUD RPCs, image upload slots, storage RLS.
-- Context: TH-02/EPIC-02/US-01 BE; docs/themes/TH-02-product-pricing/harness/*
-- Safety: idempotent ; low lock impact on empty/new schema
-- Storage bucket: catalog-product-images (see supabase/config.toml)

create schema if not exists catalog;

do $$
begin
  if not exists (
    select 1
    from pg_type t
    join pg_namespace n on n.oid = t.typnamespace
    where n.nspname = 'catalog'
      and t.typname = 'product_business_status'
  ) then
    create type catalog.product_business_status as enum ('active', 'inactive');
  end if;

  if not exists (
    select 1
    from pg_type t
    join pg_namespace n on n.oid = t.typnamespace
    where n.nspname = 'catalog'
      and t.typname = 'product_readiness_status'
  ) then
    create type catalog.product_readiness_status as enum (
      'incomplete',
      'ready_to_sell',
      'ready_to_receive'
    );
  end if;
end $$;

create table if not exists catalog.products (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null,
  idempotency_key uuid null,
  name text not null,
  trade_name text null,
  sku text null,
  sku_normalized text null,
  barcode text null,
  barcode_normalized text null,
  description text null,
  note text null,
  tracking_mode text not null default 'none',
  expiry_required boolean not null default false,
  business_status catalog.product_business_status not null default 'active',
  deleted_at timestamptz null,
  created_at timestamptz not null default now(),
  created_by uuid not null,
  updated_at timestamptz not null default now(),
  updated_by uuid not null,
  version integer not null default 1,
  constraint chk_products_name_not_blank
    check (length(btrim(name)) > 0),
  constraint chk_products_sku_normalization
    check (sku is null or sku_normalized is not null),
  constraint chk_products_barcode_normalization
    check (barcode is null or barcode_normalized is not null),
  constraint chk_products_tracking_mode
    check (tracking_mode in ('none', 'lot')),
  constraint chk_products_expiry_requires_lot
    check (not expiry_required or tracking_mode = 'lot')
);

create unique index if not exists uq_products_tenant_idempotency_key
  on catalog.products (tenant_id, idempotency_key)
  where idempotency_key is not null;

-- Unique per tenant including soft-deleted (FR-02 BR-05).
create unique index if not exists uq_products_tenant_sku_normalized
  on catalog.products (tenant_id, sku_normalized)
  where sku_normalized is not null;

create unique index if not exists uq_products_tenant_barcode_normalized
  on catalog.products (tenant_id, barcode_normalized)
  where barcode_normalized is not null;

create table if not exists catalog.image_upload_slots (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null,
  storage_key text not null,
  actor_id uuid not null,
  file_name text not null,
  content_type text not null,
  byte_size bigint not null,
  status text not null default 'pending'
    check (status in ('pending', 'uploaded', 'consumed', 'expired')),
  expires_at timestamptz not null,
  consumed_at timestamptz null,
  created_at timestamptz not null default now(),
  constraint chk_image_upload_slots_storage_key_not_blank
    check (length(btrim(storage_key)) > 0),
  constraint chk_image_upload_slots_byte_size_positive
    check (byte_size > 0)
);

create unique index if not exists uq_image_upload_slots_storage_key
  on catalog.image_upload_slots (storage_key);

create index if not exists idx_image_upload_slots_tenant_status
  on catalog.image_upload_slots (tenant_id, status, expires_at);

create table if not exists catalog.product_images (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null,
  product_id uuid not null references catalog.products (id) on delete cascade,
  storage_key text not null,
  file_url text null,
  is_primary boolean not null default false,
  sort_order integer not null default 0,
  processing_status text not null default 'ready'
    check (processing_status in ('pending', 'processing', 'ready', 'failed')),
  upload_slot_id uuid null references catalog.image_upload_slots (id),
  created_at timestamptz not null default now(),
  constraint chk_product_images_storage_key_not_blank
    check (length(btrim(storage_key)) > 0)
);

create index if not exists idx_product_images_product_id
  on catalog.product_images (product_id);

alter table catalog.product_images
  add column if not exists processing_status text not null default 'ready'
    check (processing_status in ('pending', 'processing', 'ready', 'failed'));

alter table catalog.product_images
  add column if not exists upload_slot_id uuid null
    references catalog.image_upload_slots (id);

create table if not exists catalog.product_units (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null,
  product_id uuid not null references catalog.products (id) on delete cascade,
  unit_name text not null,
  is_base_unit boolean not null default false,
  conversion_rate_to_base numeric not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint chk_product_units_name_not_blank
    check (length(btrim(unit_name)) > 0),
  constraint chk_product_units_conversion_positive
    check (conversion_rate_to_base > 0)
);

create unique index if not exists uq_product_units_one_base
  on catalog.product_units (product_id)
  where is_base_unit = true;

create table if not exists catalog.product_readiness (
  product_id uuid primary key references catalog.products (id) on delete cascade,
  tenant_id uuid not null,
  status catalog.product_readiness_status not null default 'incomplete',
  blockers jsonb not null default '[]'::jsonb,
  updated_at timestamptz not null default now()
);

create table if not exists catalog.product_change_history (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null,
  product_id uuid not null references catalog.products (id) on delete cascade,
  action text not null,
  payload jsonb not null default '{}'::jsonb,
  actor_id uuid not null,
  created_at timestamptz not null default now()
);

create index if not exists idx_product_change_history_product_id
  on catalog.product_change_history (product_id, created_at desc);

create or replace function catalog._catalog_storage_tenant_id(p_name text)
returns uuid
language sql
immutable
as $$
  select nullif((storage.foldername(p_name))[1], '')::uuid;
$$;

create or replace function catalog._catalog_storage_is_staging_path(p_name text)
returns boolean
language sql
immutable
as $$
  select coalesce((storage.foldername(p_name))[2], '') = 'staging';
$$;

create or replace function catalog._catalog_storage_is_products_path(p_name text)
returns boolean
language sql
immutable
as $$
  select coalesce((storage.foldername(p_name))[2], '') = 'products';
$$;

create or replace function catalog._catalog_storage_tenant_allowed(p_name text)
returns boolean
language sql
stable
security definer
set search_path = catalog, iam, storage, pg_temp
as $$
  select iam.has_permission(
    catalog._catalog_storage_tenant_id(p_name),
    'catalog.product.create'
  );
$$;

create or replace function catalog.check_duplicate_product_code(
  p_tenant_id uuid,
  p_sku text default null,
  p_barcode text default null,
  p_exclude_product_id uuid default null
)
returns table (
  duplicate_field text,
  product_id uuid,
  product_name text,
  matched_value text
)
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_sku_normalized text;
  v_barcode_normalized text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.create') then
    raise exception 'permission denied: catalog.product.create';
  end if;

  v_sku_normalized := nullif(lower(btrim(coalesce(p_sku, ''))), '');
  v_barcode_normalized := nullif(btrim(coalesce(p_barcode, '')), '');

  return query
  select m.duplicate_field, m.product_id, m.product_name, m.matched_value
  from (
    select
      'sku'::text as duplicate_field,
      p.id as product_id,
      p.name as product_name,
      p.sku as matched_value
    from catalog.products p
    where p.tenant_id = p_tenant_id
      and v_sku_normalized is not null
      and p.sku_normalized = v_sku_normalized
      and (p_exclude_product_id is null or p.id <> p_exclude_product_id)
    union all
    select
      'barcode'::text as duplicate_field,
      p.id as product_id,
      p.name as product_name,
      p.barcode as matched_value
    from catalog.products p
    where p.tenant_id = p_tenant_id
      and v_barcode_normalized is not null
      and p.barcode_normalized = v_barcode_normalized
      and (p_exclude_product_id is null or p.id <> p_exclude_product_id)
  ) m
  order by m.duplicate_field, m.product_name;
end;
$$;

create or replace function catalog._image_extension_from_name(p_file_name text)
returns text
language plpgsql
immutable
as $$
declare
  v_ext text;
begin
  v_ext := lower(regexp_replace(coalesce(p_file_name, ''), '^.*\.', ''));
  if v_ext in ('jpg', 'jpeg', 'png', 'webp') then
    if v_ext = 'jpg' then
      return 'jpeg';
    end if;
    return v_ext;
  end if;
  return 'jpeg';
end;
$$;

create or replace function catalog.request_product_image_upload(
  p_tenant_id uuid,
  p_file_name text,
  p_content_type text,
  p_byte_size bigint,
  p_actor_id uuid default auth.uid()
)
returns table (
  slot_id uuid,
  storage_key text,
  expires_at timestamptz
)
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_slot_id uuid := gen_random_uuid();
  v_ext text;
  v_storage_key text;
  v_expires_at timestamptz := now() + interval '1 hour';
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if p_actor_id is null or p_actor_id <> auth.uid() then
    raise exception 'actor mismatch';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.create') then
    raise exception 'permission denied: catalog.product.create';
  end if;

  if length(btrim(coalesce(p_file_name, ''))) = 0 then
    raise exception 'file name is required';
  end if;

  if p_byte_size is null or p_byte_size <= 0 then
    raise exception 'byte size must be positive';
  end if;

  if p_byte_size > 10485760 then
    raise exception 'file too large';
  end if;

  if lower(coalesce(p_content_type, '')) not in (
    'image/jpeg', 'image/png', 'image/webp'
  ) then
    raise exception 'unsupported content type';
  end if;

  v_ext := catalog._image_extension_from_name(p_file_name);
  v_storage_key := p_tenant_id::text || '/staging/' || v_slot_id::text || '/original.' || v_ext;

  insert into catalog.image_upload_slots (
    id,
    tenant_id,
    storage_key,
    actor_id,
    file_name,
    content_type,
    byte_size,
    status,
    expires_at
  )
  values (
    v_slot_id,
    p_tenant_id,
    v_storage_key,
    p_actor_id,
    btrim(p_file_name),
    lower(p_content_type),
    p_byte_size,
    'pending',
    v_expires_at
  );

  return query
  select v_slot_id, v_storage_key, v_expires_at;
end;
$$;

create or replace function catalog._consume_image_upload_slot(
  p_tenant_id uuid,
  p_storage_key text,
  p_actor_id uuid
)
returns uuid
language plpgsql
security definer
set search_path = catalog, pg_temp
as $$
declare
  v_slot_id uuid;
begin
  update catalog.image_upload_slots s
  set
    status = 'consumed',
    consumed_at = now()
  where s.tenant_id = p_tenant_id
    and s.storage_key = btrim(p_storage_key)
    and s.status in ('pending', 'uploaded')
    and s.expires_at > now()
    and s.actor_id = p_actor_id
  returning s.id into v_slot_id;

  if v_slot_id is null then
    raise exception 'invalid or expired image upload slot';
  end if;

  return v_slot_id;
end;
$$;

create or replace function catalog.create_product(
  p_tenant_id uuid,
  p_name text,
  p_actor_id uuid default auth.uid(),
  p_trade_name text default null,
  p_sku text default null,
  p_barcode text default null,
  p_description text default null,
  p_note text default null,
  p_images jsonb default '[]'::jsonb,
  p_base_unit_name text default null,
  p_readiness_status text default 'incomplete',
  p_readiness_blockers jsonb default '[]'::jsonb,
  p_idempotency_key uuid default null
)
returns uuid
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_product_id uuid;
  v_sku_normalized text;
  v_barcode_normalized text;
  v_base_unit_name text;
  v_image jsonb;
  v_readiness_status catalog.product_readiness_status;
  v_storage_key text;
  v_slot_id uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if p_actor_id is null or p_actor_id <> auth.uid() then
    raise exception 'actor mismatch';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.create') then
    raise exception 'permission denied: catalog.product.create';
  end if;

  if length(btrim(coalesce(p_name, ''))) = 0 then
    raise exception 'product name is required';
  end if;

  if p_idempotency_key is not null then
    select p.id
    into v_product_id
    from catalog.products p
    where p.tenant_id = p_tenant_id
      and p.idempotency_key = p_idempotency_key;

    if v_product_id is not null then
      return v_product_id;
    end if;
  end if;

  v_sku_normalized := nullif(lower(btrim(coalesce(p_sku, ''))), '');
  v_barcode_normalized := nullif(btrim(coalesce(p_barcode, '')), '');
  v_base_unit_name := nullif(btrim(coalesce(p_base_unit_name, '')), '');

  if v_sku_normalized is not null
    and exists (
      select 1
      from catalog.products p
      where p.tenant_id = p_tenant_id
        and p.sku_normalized = v_sku_normalized
    ) then
    raise exception 'duplicate sku';
  end if;

  if v_barcode_normalized is not null
    and exists (
      select 1
      from catalog.products p
      where p.tenant_id = p_tenant_id
        and p.barcode_normalized = v_barcode_normalized
    ) then
    raise exception 'duplicate barcode';
  end if;

  v_readiness_status := coalesce(
    p_readiness_status::catalog.product_readiness_status,
    'incomplete'::catalog.product_readiness_status
  );

  begin
    insert into catalog.products (
      tenant_id,
      idempotency_key,
      name,
      trade_name,
      sku,
      sku_normalized,
      barcode,
      barcode_normalized,
      description,
      note,
      business_status,
      created_by,
      updated_by
    )
    values (
      p_tenant_id,
      p_idempotency_key,
      btrim(p_name),
      nullif(btrim(coalesce(p_trade_name, '')), ''),
      nullif(btrim(coalesce(p_sku, '')), ''),
      v_sku_normalized,
      nullif(btrim(coalesce(p_barcode, '')), ''),
      v_barcode_normalized,
      nullif(btrim(coalesce(p_description, '')), ''),
      nullif(btrim(coalesce(p_note, '')), ''),
      'active',
      p_actor_id,
      p_actor_id
    )
    returning id into v_product_id;
  exception
    when unique_violation then
      if v_sku_normalized is not null
        and exists (
          select 1 from catalog.products p
          where p.tenant_id = p_tenant_id and p.sku_normalized = v_sku_normalized
        ) then
        raise exception 'duplicate sku';
      end if;
      if v_barcode_normalized is not null
        and exists (
          select 1 from catalog.products p
          where p.tenant_id = p_tenant_id and p.barcode_normalized = v_barcode_normalized
        ) then
        raise exception 'duplicate barcode';
      end if;
      raise;
  end;

  if p_images is not null and jsonb_typeof(p_images) = 'array' then
    for v_image in select * from jsonb_array_elements(p_images)
    loop
      v_storage_key := btrim(v_image ->> 'storage_key');
      if v_storage_key is null or length(v_storage_key) = 0 then
        continue;
      end if;

      begin
        v_slot_id := catalog._consume_image_upload_slot(
          p_tenant_id,
          v_storage_key,
          p_actor_id
        );
      exception
        when others then
          -- AF-04: skip invalid image, continue create with remaining images.
          continue;
      end;

      insert into catalog.product_images (
        tenant_id,
        product_id,
        storage_key,
        file_url,
        is_primary,
        sort_order,
        processing_status,
        upload_slot_id
      )
      values (
        p_tenant_id,
        v_product_id,
        v_storage_key,
        nullif(btrim(coalesce(v_image ->> 'url', '')), ''),
        coalesce((v_image ->> 'is_primary')::boolean, false),
        coalesce((v_image ->> 'sort_order')::integer, 0),
        'ready',
        v_slot_id
      );
    end loop;
  end if;

  if v_base_unit_name is not null then
    insert into catalog.product_units (
      tenant_id,
      product_id,
      unit_name,
      is_base_unit,
      conversion_rate_to_base
    )
    values (
      p_tenant_id,
      v_product_id,
      v_base_unit_name,
      true,
      1
    );
  end if;

  insert into catalog.product_readiness (
    product_id,
    tenant_id,
    status,
    blockers
  )
  values (
    v_product_id,
    p_tenant_id,
    v_readiness_status,
    coalesce(p_readiness_blockers, '[]'::jsonb)
  );

  insert into catalog.product_change_history (
    tenant_id,
    product_id,
    action,
    payload,
    actor_id
  )
  values (
    p_tenant_id,
    v_product_id,
    'CREATED',
    jsonb_build_object(
      'product_id', v_product_id,
      'name', btrim(p_name),
      'sku', nullif(btrim(coalesce(p_sku, '')), ''),
      'barcode', nullif(btrim(coalesce(p_barcode, '')), '')
    ),
    p_actor_id
  );

  return v_product_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- Storage: bucket catalog-product-images + RLS (signed upload / read)
-- Path layout: {tenant_id}/staging/{slot_id}/original.{ext}
--              {tenant_id}/products/{product_id}/{image_id}/...
-- ---------------------------------------------------------------------------

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'catalog-product-images',
  'catalog-product-images',
  false,
  10485760,
  array['image/jpeg', 'image/png', 'image/webp']::text[]
)
on conflict (id) do update
set
  public = excluded.public,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists catalog_product_images_staging_insert on storage.objects;
create policy catalog_product_images_staging_insert
on storage.objects
for insert
to authenticated
with check (
  bucket_id = 'catalog-product-images'
  and catalog._catalog_storage_is_staging_path(name)
  and catalog._catalog_storage_tenant_allowed(name)
);

drop policy if exists catalog_product_images_staging_select on storage.objects;
create policy catalog_product_images_staging_select
on storage.objects
for select
to authenticated
using (
  bucket_id = 'catalog-product-images'
  and catalog._catalog_storage_is_staging_path(name)
  and catalog._catalog_storage_tenant_allowed(name)
);

drop policy if exists catalog_product_images_staging_update on storage.objects;
create policy catalog_product_images_staging_update
on storage.objects
for update
to authenticated
using (
  bucket_id = 'catalog-product-images'
  and catalog._catalog_storage_is_staging_path(name)
  and catalog._catalog_storage_tenant_allowed(name)
)
with check (
  bucket_id = 'catalog-product-images'
  and catalog._catalog_storage_is_staging_path(name)
  and catalog._catalog_storage_tenant_allowed(name)
);

drop policy if exists catalog_product_images_products_select on storage.objects;
create policy catalog_product_images_products_select
on storage.objects
for select
to authenticated
using (
  bucket_id = 'catalog-product-images'
  and catalog._catalog_storage_is_products_path(name)
  and catalog._catalog_storage_tenant_allowed(name)
);

